import { Badge } from "@/registry/erbium/ui/badge";

export default function SpinnerBadge() {
  return (
    <div className="flex items-center gap-group [--radius:1.2rem]">
      <Badge loading>Syncing</Badge>
      <Badge variant="secondary" loading>
        Updating
      </Badge>
      <Badge variant="outline" loading>
        Processing
      </Badge>
    </div>
  );
}

import ExampleSpinnerBadge from "../examples/spinner-badge";

const Example = () => (
  <div className="w-full min-w-72 max-w-2xl p-4">
    <ExampleSpinnerBadge />
  </div>
);

export default Example;
